{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://scripts/pirate_ship.gd","contents":"# Base script that represents the physics body of a pirate ship. Manages the 
# pirate's squad, squad leader, and movement speeds of the ship.
class_name PirateShip
extends CharacterBody2D

signal died
signal squad_leader_changed(current_patrol_point)

const DECELERATION_RADIUS := deg_to_rad(45)
const ALIGNMENT_TOLERANCE := deg_to_rad(5)

# Represents the ship on the minimap. Use a MapIcon resource.
@export var map_icon: Resource

@export var health_max := 100

@export var linear_speed_max := 200.0
@export var acceleration_max := 15.0
@export var drag_factor := 0.04
@export var angular_speed_max := 270
@export var angular_acceleration_max := 15
@export var angular_drag_factor := 0.1
@export var distance_from_target_min := 200.0
@export var distance_from_obstacles_min := 200.0
@export var projectile_mask := 0 # (int, LAYERS_2D_PHYSICS)
@export var explosion_effect: PackedScene

var current_target: Node
var target_agent: GSAISteeringAgent
var squaddies: Array

var is_squad_leader := false
var patrol_point := Vector2.ZERO
var squad_leader: CharacterBody2D

var agent := await GSAICharacterBody2DAgent.new(self)
var squad_proximity := GSAIInfiniteProximity.new(agent, [])
var target_proximity := GSAIRadiusProximity.new(agent, [], distance_from_target_min)
var world_proximity := GSAIRadiusProximity.new(agent, [], distance_from_obstacles_min)
var faction_proximity := GSAIRadiusProximity.new(agent, [], 500)
var rng := RandomNumberGenerator.new()

var _acceleration := GSAITargetAcceleration.new()
var _velocity := Vector2.ZERO
var _angular_velocity := 0.0
var _arrive_home_blend: GSAIBlend
var _pursue_face_blend: GSAIBlend
var _health := health_max

@onready var gun := $Gun
@onready var state_machine := $StateMachine


func _ready() -> void:
	rng.randomize()
	# ----- Agent config -----
	agent.linear_acceleration_max = acceleration_max
	agent.linear_speed_max = linear_speed_max

	agent.angular_acceleration_max = deg_to_rad(angular_acceleration_max)
	agent.angular_speed_max = deg_to_rad(angular_speed_max)

	agent.bounding_radius = (MathUtils.get_triangle_circumcircle_radius($CollisionShape3D.polygon))

	agent.linear_drag_percentage = drag_factor
	agent.angular_drag_percentage = angular_drag_factor

	Events.damaged.connect(_on_self_damaged)
	Events.target_aggroed.connect(_on_Target_Aggroed)
	
	$AggroArea.body_entered.connect(_on_Body_entered_aggro_radius)


func setup_world_objects(world_objects: Array) -> void:
	world_proximity.agents.clear()
	for wo_ref in world_objects:
		var wo: Node2D = wo_ref.get_ref()
		if not wo:
			continue
		var object_agent: GSAIAgentLocation = wo.agent_location
		world_proximity.agents.append(object_agent)


func setup_squad(
	_is_squad_leader: bool,
	_squad_leader: CharacterBody2D,
	_patrol_point: Vector2,
	_squaddies: Array
) -> void:
	is_squad_leader = _is_squad_leader
	squad_leader = _squad_leader
	patrol_point = _patrol_point
	var squaddies_ref := []
	for s in _squaddies:
		squad_proximity.agents.append(s.agent)
		squaddies_ref.append(weakref(s))
	squaddies = squaddies_ref
	if not is_squad_leader:
		Events.squad_leader_changed.connect(_on_Leader_changed)


func setup_faction(pirates: Array) -> void:
	for p in pirates:
		faction_proximity.agents.append(p.agent)


func _die() -> void:
	var effect: Node2D = explosion_effect.instantiate()
	ObjectRegistry.register_effect(effect)
	effect.global_position = global_position
	died.emit()
	var new_leader: CharacterBody2D
	for squaddie_ref in squaddies:
		var squaddie: CharacterBody2D = squaddie_ref.get_ref()
		if not squaddie:
			continue
		# FIXME: I had an error because a Projectile was in the squaddies array
		# We should ensure this cannot happen, and squaddies are all from the faction
		if not squaddie.is_in_group("Enemies"):
			continue
		if squaddie._health > 0:
			new_leader = squaddie
			break
	Events.squad_leader_changed.emit(self, new_leader, patrol_point)

	queue_free()


func _on_self_damaged(target: Node, amount: int, _origin: Node) -> void:
	if not target == self:
		return

	_health -= amount

	if _origin:
		Events.target_aggroed.emit(squad_leader, _origin)

	if _health <= 0:
		_die()


func _on_Leader_changed(
	old_leader: CharacterBody2D, new_leader: CharacterBody2D, current_patrol_point: Vector2
) -> void:
	if old_leader == squad_leader:
		squaddies.erase(old_leader)
		squad_proximity.agents.erase(old_leader.agent)
		squad_leader = new_leader
		if new_leader == self:
			is_squad_leader = true
			patrol_point = current_patrol_point
		squad_leader_changed.emit(current_patrol_point)


func _on_Body_entered_aggro_radius(collider: PhysicsBody2D) -> void:
	Events.target_aggroed.emit(squad_leader, collider)


func _on_Target_Aggroed(leader: Node, target: PhysicsBody2D) -> void:
	if squad_leader == leader:
		state_machine.transition_to("Attack", {target = target})
"}}

{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://scripts/projectile.gd","contents":"# A physics body that moves in a straight line at a constant speed until it runs
# into something that it's able to collide with, at which point it signals
# damage.
class_name Projectile
extends CharacterBody2D

const _AUDIO_SAMPLES = [
	preload("weapons_plasma_shot_01.wav"),
	preload("weapons_plasma_shot_02.wav"),
	preload("weapons_plasma_shot_03.wav"),
	preload("weapons_plasma_shot_04.wav"),
	preload("weapons_plasma_shot_05.wav"),
	preload("weapons_plasma_shot_06.wav"),
]

@export var speed := 1650.0
@export var damage := 10.0
@export var distortion_emitter: PackedScene

var is_active := true: set = set_is_active
var direction := Vector2.ZERO
var shooter: Node

@onready var tween : Tween
@onready var sprite := $Sprite2D
@onready var player := $AnimationPlayer
@onready var remote_transform := $DistortionTransform
@onready var visibility_notifier: VisibleOnScreenNotifier2D = $VisibleOnScreenNotifier2D
@onready var collider: CollisionShape2D = $CollisionShape2D
@onready var audio: AudioStreamPlayer2D = $AudioStreamPlayer2D


func _ready() -> void:
	direction = -GSAIUtils.angle_to_vector2(rotation)
	visibility_notifier.screen_exited.connect(queue_free)

	sprite.material = sprite.material.duplicate()
	player.play("Flicker")

	var emitter := distortion_emitter.instantiate()
	ObjectRegistry.register_distortion_effect(emitter)
	remote_transform.remote_path = emitter.get_path()

	appear()

#E 0:01:17:0974   Projectile.gd:50 @ _physics_process(): Error calling from signal 'damaged' to callable: 'CharacterBody2D(PirateShip.gd)::_on_self_damaged': Cannot convert argument 3 from Object to Object.

func _physics_process(delta: float) -> void:
	var collision := move_and_collide(direction * speed * delta)
	if collision:
		Events.damaged.emit(collision.get_collider(), damage, shooter)
		die()


func appear() -> void:
	self.is_active = true
	tween = create_tween()
	tween.tween_method(_fade, 0.0, 1.0, 0.05).set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_LINEAR)
	tween.tween_property(
		self, "scale", scale, 0.05
	).from(scale / 5.0).set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_LINEAR)
	tween.play()

	audio.stream = _AUDIO_SAMPLES[randi() % _AUDIO_SAMPLES.size()]
	audio.play()


func die() -> void:
	self.is_active = false
	tween = create_tween()
	tween.tween_method(_fade, 1.0, 0.0, 0.15).set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_LINEAR)
	tween.play()
	await tween.finished
	queue_free()


func set_is_active(value: bool) -> void:
	is_active = value
	collider.disabled = not is_active
	set_physics_process(is_active)


func _fade(value: float) -> void:
	sprite.material.set_shader_parameter("fade_amount", value)
"}}

{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://scripts/example_player.gd","contents":"extends CharacterBody3D

# Walking variables.
const norm_grav = -38.8
const MAX_SPEED = 22
const JUMP_SPEED = 26
const ACCEL = 8.5
# Sprinting variables. Similar to the variables above, just allowing for quicker movement
const MAX_SPRINT_SPEED = 34
const SPRINT_ACCEL = 18
# How fast we slow down, and the steepest angle we can climb.
const DEACCEL = 28
const MAX_SLOPE_ANGLE = 40
# How fast the bullets launch
const LEFT_MOUSE_FIRE_TIME = 0.15
const BULLET_SPEED = 100

var vel = Vector3()
# A vector for storing the direction the player intends to walk towards.
var dir = Vector3()
# A boolean to track whether or not we are sprinting
var is_sprinting = false

# You may need to adjust depending on the sensitivity of your mouse
var MOUSE_SENSITIVITY = 0.08

# A boolean for tracking whether the jump button is down
var jump_button_down = false

# The current lean value (our position on the lean track) and the path follow node
var lean_value = 0.5

# A variable for tracking if the right mouse button is down.
var right_mouse_down = false
# A variable for tracking if we can fire using the left mouse button
var left_mouse_timer = 0

# A boolean for tracking whether we can change animations or not
var anim_done = true
# The current animation name
var current_anim = "Starter"

# The simple bullet rigidbody
var simple_bullet = preload("res://fps/simple_bullet.tscn")

# We need the camera for getting directional vectors. We rotate ourselves on the Y-axis using
# the camera_holder to avoid rotating on more than one axis at a time.
@onready var camera_holder = $CameraHolder
@onready var camera = $CameraHolder/LeanPath/PathFollow3D/IK_LookAt_Chest/Camera3D
@onready var path_follow_node = $CameraHolder/LeanPath/PathFollow3D
# The animation player for aiming down the sights.
@onready var anim_player = $CameraHolder/AnimationPlayer
# The end of the pistol.
@onready var pistol_end = $CameraHolder/Weapon/Pistol/PistolEnd


func _ready():
	anim_player.animation_finished.connect(animation_finished)

	set_physics_process(true)
	Input.set_mouse_mode(Input.MOUSE_MODE_CAPTURED)
	set_process_input(true)


func _physics_process(delta):
	process_input(delta)
	process_movement(delta)


func process_input(delta):
	# Reset dir, so our previous movement does not effect us
	dir = Vector3()
	# Get the camera's global transform so we can use its directional vectors
	var cam_xform = camera.get_global_transform()

	# ----------------------------------
	# Walking
	if Input.is_key_pressed(KEY_UP) or Input.is_key_pressed(KEY_W):
		dir += -cam_xform.basis[2]
	if Input.is_key_pressed(KEY_DOWN) or Input.is_key_pressed(KEY_S):
		dir += cam_xform.basis[2]
	if Input.is_key_pressed(KEY_LEFT) or Input.is_key_pressed(KEY_A):
		dir += -cam_xform.basis[0]
	if Input.is_key_pressed(KEY_RIGHT) or Input.is_key_pressed(KEY_D):
		dir += cam_xform.basis[0]

	if Input.is_action_just_pressed(&"ui_cancel"):
		if Input.get_mouse_mode() == Input.MOUSE_MODE_VISIBLE:
			Input.set_mouse_mode(Input.MOUSE_MODE_CAPTURED)
		else:
			Input.set_mouse_mode(Input.MOUSE_MODE_VISIBLE)

	if Input.is_mouse_button_pressed(2):
		if not right_mouse_down:
			right_mouse_down = true

			if anim_done:
				if current_anim != "Aiming":
					anim_player.play(&"Aiming")
					current_anim = "Aiming"
				else:
					anim_player.play(&"Idle")
					current_anim = "Idle"

				anim_done = false
	else:
		right_mouse_down = false

	if Input.is_mouse_button_pressed(1):
		if left_mouse_timer <= 0:
			left_mouse_timer = LEFT_MOUSE_FIRE_TIME

			# Create a bullet
			var new_bullet = simple_bullet.instantiate()
			get_tree().root.add_child(new_bullet)
			new_bullet.global_transform = pistol_end.global_transform
			new_bullet.linear_velocity = new_bullet.global_transform.basis.z * BULLET_SPEED
	if left_mouse_timer > 0:
		left_mouse_timer -= delta
	# ----------------------------------

	# ----------------------------------
	# Sprinting
	if Input.is_key_pressed(KEY_SHIFT):
		is_sprinting = true
	else:
		is_sprinting = false
	# ----------------------------------

	# ----------------------------------
	# Jumping
	if Input.is_key_pressed(KEY_SPACE):
		if not jump_button_down:
			jump_button_down = true
			if is_on_floor():
				vel.y = JUMP_SPEED
	else:
		jump_button_down = false
	# ----------------------------------

	# ----------------------------------
	# Leaning
	if Input.is_key_pressed(KEY_Q):
		lean_value += 1.2 * delta
	elif Input.is_key_pressed(KEY_E):
		lean_value -= 1.2 * delta
	else:
		if lean_value > 0.5:
			lean_value -= 1 * delta
			if lean_value < 0.5:
				lean_value = 0.5
		elif lean_value < 0.5:
			lean_value += 1 * delta
			if lean_value > 0.5:
				lean_value = 0.5

	lean_value = clamp(lean_value, 0, 1)
	path_follow_node.h_offset = lean_value
	if lean_value < 0.5:
		var lerp_value = lean_value * 2
		path_follow_node.rotation_degrees.z = (20 * (1 - lerp_value))
	else:
		var lerp_value = (lean_value - 0.5) * 2
		path_follow_node.rotation_degrees.z = (-20 * lerp_value)
	# ----------------------------------


func process_movement(delta):
	var grav = norm_grav

	dir.y = 0
	dir = dir.normalized()

	vel.y += delta * grav

	var hvel = vel
	hvel.y = 0

	var target = dir
	if is_sprinting:
		target *= MAX_SPRINT_SPEED
	else:
		target *= MAX_SPEED

	var accel
	if dir.dot(hvel) > 0:
		if not is_sprinting:
			accel = ACCEL
		else:
			accel = SPRINT_ACCEL
	else:
		accel = DEACCEL

	hvel = hvel.lerp(target, accel * delta)

	vel.x = hvel.x
	vel.z = hvel.z

	# TODO: This information should be set to the CharacterBody properties instead of arguments.
	velocity = vel
	move_and_slide()


# Mouse based camera movement
func _input(event):
	if event is InputEventMouseMotion and Input.get_mouse_mode() == Input.MOUSE_MODE_CAPTURED:
		rotate_y(deg_to_rad(event.screen_relative.x * MOUSE_SENSITIVITY * -1))
		camera_holder.rotate_x(deg_to_rad(event.screen_relative.y * MOUSE_SENSITIVITY))

		# We need to clamp the camera's rotation so we cannot rotate ourselves upside down
		var camera_rot = camera_holder.rotation_degrees
		if camera_rot.x < -40:
			camera_rot.x = -40
		elif camera_rot.x > 60:
			camera_rot.x = 60

		camera_holder.rotation_degrees = camera_rot

	else:
		pass


func animation_finished(_anim):
	anim_done = true
"}}

{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://scripts/Mob.gd","contents":"extends CharacterBody3D

# Emitted when the player jumped on the mob.
signal squashed

## Minimum speed of the mob in meters per second.
@export var min_speed = 10
## Maximum speed of the mob in meters per second.
@export var max_speed = 18


func _physics_process(_delta):
	move_and_slide()


func initialize(start_position, player_position):
	# Ignore the player's height, so that the mob's orientation is not slightly
	# shifted if the mob spawns while the player is jumping.
	var target = Vector3(player_position.x, start_position.y, player_position.z)
	look_at_from_position(start_position, target, Vector3.UP)

	# Rotate this mob randomly within range of -45 and +45 degrees,
	# so that it doesn't move directly towards the player.
	rotate_y(randf_range(-PI / 4, PI / 4))

	var random_speed = randf_range(min_speed, max_speed)
	# We calculate a forward velocity first, which represents the speed.
	velocity = Vector3.FORWARD * random_speed
	# We then rotate the vector based on the mob's Y rotation to move in the direction it's looking.
	velocity = velocity.rotated(Vector3.UP, rotation.y)

	$AnimationPlayer.speed_scale = random_speed / min_speed


func squash():
	squashed.emit()
	queue_free()


func _on_visible_on_screen_notifier_screen_exited():
	queue_free()
"}}

{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://scripts/enemy.gd","contents":"class_name Enemy
extends CharacterBody2D

enum State {
	WALKING,
	DEAD,
}

const WALK_SPEED = 22.0

var _state := State.WALKING

@onready var gravity: int = ProjectSettings.get(&"physics/2d/default_gravity")
@onready var platform_detector := $PlatformDetector as RayCast2D
@onready var floor_detector_left := $FloorDetectorLeft as RayCast2D
@onready var floor_detector_right := $FloorDetectorRight as RayCast2D
@onready var sprite := $Sprite2D as Sprite2D
@onready var animation_player := $AnimationPlayer as AnimationPlayer


func _physics_process(delta: float) -> void:
	if _state == State.WALKING and velocity.is_zero_approx():
		velocity.x = WALK_SPEED
	velocity.y += gravity * delta
	if not floor_detector_left.is_colliding():
		velocity.x = WALK_SPEED
	elif not floor_detector_right.is_colliding():
		velocity.x = -WALK_SPEED

	if is_on_wall():
		velocity.x = -velocity.x

	move_and_slide()

	if velocity.x > 0.0:
		sprite.scale.x = 0.8
	elif velocity.x < 0.0:
		sprite.scale.x = -0.8

	var animation := get_new_animation()
	if animation != animation_player.current_animation:
		animation_player.play(animation)


func destroy() -> void:
	_state = State.DEAD
	velocity = Vector2.ZERO


func get_new_animation() -> StringName:
	var animation_new: StringName
	if _state == State.WALKING:
		if velocity.x == 0:
			animation_new = &"idle"
		else:
			animation_new = &"walk"
	else:
		animation_new = &"destroy"
	return animation_new
"}}

{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://scripts/player_camera.gd","contents":"# The main camera that follows the location of the player. It manages
# zooming out when the map button is pressed, and manages the creation
# of a duplicate itself that will live in the minimap viewport, and will follow
# the original's position in the world using a `RemoteTransform2D`.
#
# The camera supports zooming and camera shake.
extends Camera2D

const SHAKE_EXPONENT := 1.8

@export var max_zoom := 5.0
@export var decay_rate := 1.0
@export var shake_offset_multiplier := Vector2(100.0, 100.0)

var shake_amount := 0.0: set = set_shake_amount
var noise_y : float = 0.0

var _start_zoom := zoom
var _start_position := Vector2.ZERO

@onready var remote_map := $RemoteMap
@onready var remote_distort := $RemoteDistort
@onready var tween: Tween
@onready var noise := FastNoiseLite.new()


func _ready() -> void:
	set_physics_process(false)

	Events.map_toggled.connect(_toggle_map)
	Events.explosion_occurred.connect(_on_Events_explosion_occurred)

	randomize()
	noise.seed = randi()
	noise.frequency = 4
	noise.fractal_octaves = 2
	noise.noise_type = FastNoiseLite.TYPE_PERLIN


func _physics_process(delta):
	self.shake_amount -= decay_rate * delta
	noise_y += delta
	shake()


func shake():
	var amount : float = pow(shake_amount, SHAKE_EXPONENT)
	
	if amount == 0:
		return
		
	offset = Vector2(
		shake_offset_multiplier.x * amount * noise.get_noise_2d(noise_y, noise_y / amount),
		shake_offset_multiplier.y * amount * noise.get_noise_2d(noise_y / amount, noise_y)
	)


func set_shake_amount(value):
	shake_amount = clampf(value, 0.0, 1.0)
	set_physics_process(shake_amount != 0.0)


func setup_camera_map(map: MapView) -> void:
	var camera_map := self.duplicate()
	map.register_camera(camera_map)
	remote_map.remote_path = camera_map.get_path()


func setup_distortion_camera() -> void:
	var distort_camera := self.duplicate()
	ObjectRegistry.register_distortion_effect(distort_camera)
	remote_distort.remote_path = distort_camera.get_path()


func _toggle_map(display: bool, duration: float) -> void:
	if tween and tween.is_running:
		tween.kill()
	tween = create_tween()
	if display:
		tween.tween_property(
			self,
			"zoom",
			_start_zoom,
			duration
		).from_current().set_ease(Tween.EASE_OUT_IN).set_trans(Tween.TRANS_LINEAR)
	else:
		_start_position = position
		tween.tween_property(
			self,
			"zoom",
			Vector2(max_zoom, max_zoom),
			duration
		).from_current().set_ease(Tween.EASE_OUT_IN).set_trans(Tween.TRANS_LINEAR)


func _on_Events_explosion_occurred() -> void:
	self.shake_amount += 0.6
"}}

{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://scripts/Pathfinder.gd","contents":"## Finds the path between two points among walkable cells using the AStar pathfinding algorithm.
class_name PathFinder
extends Reference

const DIRECTIONS = [Vector2.LEFT, Vector2.RIGHT, Vector2.UP, Vector2.DOWN]

var _grid: Resource
var _astar := AStar2D.new()


## Initializes the Astar2D object upon creation.
func _init(grid: Grid, walkable_cells: Array) -> void:
	_grid = grid
	var cell_mappings := {}
	for cell in walkable_cells:
		cell_mappings[cell] = _grid.as_index(cell)
	_add_and_connect_points(cell_mappings)


## Returns the path found between `start` and `end` as an array of Vector2 coordinates.
func calculate_point_path(start: Vector2, end: Vector2) -> PoolVector2Array:
	var start_index: int = _grid.as_index(start)
	var end_index: int = _grid.as_index(end)
	if _astar.has_point(start_index) and _astar.has_point(end_index):
		return _astar.get_point_path(start_index, end_index)
	else:
		return PoolVector2Array()


## Adds and connects the walkable cells to the Astar2D object.
func _add_and_connect_points(cell_mappings: Dictionary) -> void:
	for point in cell_mappings:
		_astar.add_point(cell_mappings[point], point)

	for point in cell_mappings:
		for neighbor_index in _find_neighbor_indices(point, cell_mappings):
			_astar.connect_points(cell_mappings[point], neighbor_index)


## Returns an array of the `cell`'s connectable neighbors.
func _find_neighbor_indices(cell: Vector2, cell_mappings: Dictionary) -> Array:
	var out := []
	for direction in DIRECTIONS:
		var neighbor: Vector2 = cell + direction
		if not cell_mappings.has(neighbor):
			continue
		if not _astar.are_points_connected(cell_mappings[cell], cell_mappings[neighbor]):
			out.push_back(cell_mappings[neighbor])
	return out
"}}

