{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://scripts/grid.gd","contents":"# This script creates the ImageTexture and assigns it to an existing material at runtime.
# By not having `@tool`, this avoids saving the raw image data in the scene file,
# which would make it much larger.
extends MeshInstance3D


const TEXTURE_SIZE = Vector2i(512, 512)
const GRID_SIZE = 32
const GRID_THICKNESS = 4


func _ready() -> void:
	var image := Image.create(TEXTURE_SIZE.x, TEXTURE_SIZE.y, false, Image.FORMAT_RGB8)
	# Use 1-dimensional loop as it's faster than a nested loop.
	for i in TEXTURE_SIZE.x * TEXTURE_SIZE.y:
		var x := i % TEXTURE_SIZE.y
		var y := i / TEXTURE_SIZE.y
		var color := Color()

		# Draw a grid with more contrasted points where X and Y lines meet.
		# Center the grid's lines so that lines are visible on all the texture's edges.
		if (x + GRID_THICKNESS / 2) % GRID_SIZE < GRID_THICKNESS and (y + GRID_THICKNESS / 2) % GRID_SIZE < GRID_THICKNESS:
			color.g = 0.8
		elif (x + GRID_THICKNESS / 2) % GRID_SIZE < GRID_THICKNESS or (y + GRID_THICKNESS / 2) % GRID_SIZE < GRID_THICKNESS:
			color.g = 0.25

		# Add some random noise for detail.
		color += Color(randf(), randf(), randf()) * 0.1

		image.set_pixel(x, y, color)

	image.generate_mipmaps()
	var image_texture := ImageTexture.create_from_image(image)
	get_surface_override_material(0).albedo_texture = image_texture

	image.bump_map_to_normal_map(5.0)
	image.generate_mipmaps()
	var image_texture_normal := ImageTexture.create_from_image(image)
	get_surface_override_material(0).normal_texture = image_texture_normal
"}}

{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://scripts/gsai_character_body_2d_agent.gd","contents":"# A specialized steering agent that updates itself every frame so the user does
# not have to using a CharacterBody2D
# @category - Specialized agents
class_name GSAICharacterBody2DAgent
extends GSAISpecializedAgent

# SLIDE uses `move_and_slide`
# COLLIDE uses `move_and_collide`
# POSITION changes the `global_position` directly
enum MovementType { SLIDE, COLLIDE, POSITION }

# The CharacterBody2D to keep track of
var body: CharacterBody2D: set = _set_body

# The type of movement the body executes
var movement_type: int

var _last_position: Vector2
var _body_ref: WeakRef


func _init(_body: CharacterBody2D, _movement_type: int = MovementType.SLIDE) -> void:
	if not _body.is_inside_tree():
		await(_body).ready

	self.body = _body
	self.movement_type = _movement_type

	# warning-ignore:return_value_discarded
	_body.get_tree().physics_frame.connect(_on_SceneTree_physics_frame)


# Moves the agent's `body` by target `acceleration`.
# @tags - virtual
func _apply_steering(acceleration: GSAITargetAcceleration, delta: float) -> void:
	_applied_steering = true
	match movement_type:
		MovementType.COLLIDE:
			_apply_collide_steering(acceleration.linear, delta)
		MovementType.SLIDE:
			_apply_sliding_steering(acceleration.linear, delta)
		_:
			_apply_position_steering(acceleration.linear, delta)

	_apply_orientation_steering(acceleration.angular, delta)


func _apply_sliding_steering(accel: Vector3, delta: float) -> void:
	var _body: CharacterBody2D = _body_ref.get_ref()
	if not _body:
		return

	if not _body.is_inside_tree():
		return
		
	_body.velocity = GSAIUtils.to_vector2(linear_velocity + accel * delta).limit_length(linear_speed_max)
	if apply_linear_drag:
		_body.velocity = _body.velocity.lerp(Vector2.ZERO, linear_drag_percentage)
	
	_body.move_and_slide()
	
	if calculate_velocities:
		linear_velocity = GSAIUtils.to_vector3(_body.velocity)


func _apply_collide_steering(accel: Vector3, delta: float) -> void:
	var _body: CharacterBody2D = _body_ref.get_ref()
	if not _body:
		return
		
	_body.velocity = GSAIUtils.to_vector2(
			GSAIUtils.clampedv3(linear_velocity + accel * delta, linear_speed_max)
		)
	
	if apply_linear_drag:
		_body.velocity = _body.velocity.lerp(Vector2.ZERO, linear_drag_percentage)
	
	# warning-ignore:return_value_discarded
	_body.move_and_collide(_body.velocity * delta)
	
	if calculate_velocities:
		linear_velocity = GSAIUtils.to_vector3(_body.velocity)


func _apply_position_steering(accel: Vector3, delta: float) -> void:
	var _body: CharacterBody2D = _body_ref.get_ref()
	if not _body:
		return
		
	var velocity := GSAIUtils.clampedv3(linear_velocity + accel * delta, linear_speed_max)
	if apply_linear_drag:
		velocity = velocity.lerp(Vector3.ZERO, linear_drag_percentage)
	_body.global_position += GSAIUtils.to_vector2(velocity) * delta
	if calculate_velocities:
		linear_velocity = velocity


func _apply_orientation_steering(angular_acceleration: float, delta: float) -> void:
	var _body: CharacterBody2D = _body_ref.get_ref()
	if not _body:
		return
		
	var velocity = clamp(
		angular_velocity + angular_acceleration * delta,
		-angular_speed_max,
		angular_speed_max
	)
	if apply_angular_drag:
		velocity = lerp(velocity, 0.0, angular_drag_percentage)
	_body.rotation += velocity * delta
	if calculate_velocities:
		angular_velocity = velocity


func _set_body(value: CharacterBody2D) -> void:
	body = value
	_body_ref = weakref(body)

	_last_position = value.global_position
	_last_orientation = value.rotation

	position = GSAIUtils.to_vector3(_last_position)
	orientation = _last_orientation


func _on_SceneTree_physics_frame() -> void:
	var _body: CharacterBody2D = _body_ref.get_ref()
	if not _body:
		return
	
	var current_position := _body.global_position
	var current_orientation := _body.rotation

	position = GSAIUtils.to_vector3(current_position)
	orientation = current_orientation

	if calculate_velocities:
		if _applied_steering:
			_applied_steering = false
		else:
			linear_velocity = GSAIUtils.clampedv3(
				GSAIUtils.to_vector3(current_position - _last_position), linear_speed_max
			)
			if apply_linear_drag:
				linear_velocity = linear_velocity.lerp(
					Vector3.ZERO, linear_drag_percentage
				)

			angular_velocity = clamp(
				_last_orientation - current_orientation, -angular_speed_max, angular_speed_max
			)

			if apply_angular_drag:
				angular_velocity = lerp(angular_velocity, 0.0, angular_drag_percentage)

			_last_position = current_position
			_last_orientation = current_orientation
"}}

