	move_and_slide()"}}

{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://gamestate.gd","contents":"extends Node

const DEFAULT_PORT = 10567
const MAX_PEERS = 12

var peer: ENetMultiplayerPeer
var player_name = "Player"
var players = {}

signal player_list_changed()
signal connection_failed()
signal connection_succeeded()

func _ready():
	multiplayer.peer_connected.connect(_player_connected)
	multiplayer.peer_disconnected.connect(_player_disconnected)

func _player_connected(id):
	register_player.rpc_id(id, player_name)

@rpc("any_peer")
func register_player(new_name):
	var id = multiplayer.get_remote_sender_id()
	players[id] = new_name
	player_list_changed.emit()

func host_game(name):
	player_name = name
	peer = ENetMultiplayerPeer.new()
	peer.create_server(DEFAULT_PORT, MAX_PEERS)
	multiplayer.set_multiplayer_peer(peer)

func join_game(ip, name):
	player_name = name
	peer = ENetMultiplayerPeer.new()
	peer.create_client(ip, DEFAULT_PORT)
	multiplayer.set_multiplayer_peer(peer)"}}

{"type":"tool_call","tool":"create_gdscript_file","arguments":{"script_path":"res://dungeon_generator.gd","contents":"extends Node2D

enum CellType { WALL, FLOOR }
const MAP_SIZE = Vector2(80, 45)

var _map = {}

@onready var _tilemap = $TileMapDungeon

func _ready():
	generate_new_dungeon()

func generate_new_dungeon():
	_map = _generate_random_map()
	for step in 10:
		_map = _advance_simulation()
	_paint_map()

func _generate_random_map():
	var map = {}
	for x in range(MAP_SIZE.x):
		for y in range(MAP_SIZE.y):
			map[Vector2(x, y)] = CellType.WALL if randf() < 0.5 else CellType.FLOOR
	return map

func _advance_simulation():
	var new_map = {}
	for cell in _map:
		var floor_neighbors = _count_floor_neighbors(cell)
		if _map[cell] == CellType.WALL:
			new_map[cell] = CellType.FLOOR if floor_neighbors > 4 else CellType.WALL
		else:
			new_map[cell] = CellType.WALL if 8 - floor_neighbors > 4 else CellType.FLOOR
	return new_map

func _paint_map():
	for cell in _map:
		_tilemap.set_cell(0, cell, _map[cell], Vector2i.ZERO)

func _count_floor_neighbors(loc):
	var count = 0
	for d in [Vector2.LEFT, Vector2.RIGHT, Vector2.UP, Vector2.DOWN]:
		if _map.has(loc + d) and _map[loc + d] == CellType.FLOOR:
			count += 1
	return count"}}

